  var COMBO={
  [ck('danmei','zhaoying')]: { t: '借别人的书，照自己', b: '别人的书到你手里，都成了镜子。你从字缝里看出去，看见的偏偏是自己——一个欲言又止、又舍不得走开的自己。读了半天别人，绕回来，原是跟自己说了句悄悄话。' },
  [ck('danmei','chilie')]: { t: '你要的美，得烫手', b: '你要的美是带体温的。一行字若不烫手，写得再周正，也不过是描在瓷器上的花——好看，是死的。你宁可被一句话灼一下，也懒得把一本温吞的书捱到底。' },
  [ck('danmei','qingxing')]: { t: '明知是假，偏甘心', b: '你一面挑字句的错，一面眼睁睁看它怎么骗你。明知是套路，还是入了套，就为它骗得漂亮。人对漂亮东西向来没什么骨气——你也一样，且认了。' },
  [ck('danmei','panni')]: { t: '偏爱墙缝里那朵歪花', b: '太周正的漂亮，你看两眼就腻。你偏爱不守规矩的那种美——墙缝里挤出来一朵，歪着，也开得理直气壮。合时宜的花满街都是，你要的是那点不肯低头的野。' },
  [ck('danmei','wenrou')]: { t: '美，也得能焐手', b: '你要的美，是能拿来过日子的：一盏灯、一碗热汤、一句没头没脑的好话。旁人惊天动地，你偏记得住灶台上那点微光。写得好看，又肯落到实处——琐碎里的深情，你识货。' },
  [ck('chilie','zhaoying')]: { t: '往自己心里添柴', b: '你读书，是拿别人的故事给自己添柴。火是你自己的，书不过是引子。安稳日子搁你身上，像件不合身的衣裳，穿着浑身别扭——非得烧起来，才觉出自己是活的。' },
  [ck('qingxing','zhaoying')]: { t: '待谁都客气，独没放过自己', b: '看别人，你隔着一层纱，肯留三分体面；看自己，倒把灯挑到最亮，一刀一刀，半点不饶。最狠的清醒都是对着镜子使的——你待谁都客气，独独没放过自己。' },
  [ck('panni','zhaoying')]: { t: '心里压着一句「那我呢」', b: '凡是「应该」的、「大家都这样」的，到你这儿都先打个问号。嘴上未必说，心里那句「那我呢」却压不住。这点不肯随大流的别扭，是你身上最要紧的一根刺——拔不得。' },
  [ck('wenrou','zhaoying')]: { t: '灰里扒拉出一星光', b: '惊涛骇浪你记不住，一地鸡毛里忽然亮的那一下，你倒忘不掉——一句体己话，一个不经意的好。日子过得再糙，你总有本事从灰里扒拉出一星半点的光，自己捂着。' },
  [ck('chilie','qingxing')]: { t: '清清楚楚地扑火', b: '你心里烧着，脑子却凉得很。别人扑火是糊涂，你扑火是明白——晓得会烫，手还是伸了过去。这样清清楚楚的飞蛾扑火，比什么都疼，也比什么都像你。' },
  [ck('chilie','panni')]: { t: '偏要撕开「不可以」', b: '你又烈又反，安稳是你天生的冤家。「不可以」三个字，别人绕着走，你偏要撕开看看里头是什么。这么活着，累是免不了的——可满屋子人里，亮的总是你那一个。' },
  [ck('chilie','wenrou')]: { t: '灶膛里那种火', b: '远看你是一团吓人的火，走近才知道，是灶膛里那一种——不为烧谁，是为让人有口热饭吃。嘴上不饶人，心却软得没边。那点凶，原是装给外人看的。' },
  [ck('panni','qingxing')]: { t: '安静，却谁也压不服', b: '你不吵不闹，什么都看在眼里。真到该不服的时候，一句顶人十句。世上最难对付的，从来不是嗓门大的那个——是你这样，安安静静坐着，怎么劝都劝不动、怎么压都压不服。' },
  [ck('qingxing','wenrou')]: { t: '看透了，还肯递热水', b: '人情的凉薄，你早看穿了，偏没让自己跟着凉。看透了，还肯先递出一杯热水——这份天真是攒出来的：不是没吃过亏，是吃过了，仍不肯把心焐死。' },
  [ck('panni','wenrou')]: { t: '硬壳里裹着一包软', b: '你外头一层硬壳，里头一包软。对着规矩龇牙，对着一个活生生的人，又心软得一塌糊涂。你那些「反」，闹到底都不为自己——是护着那些没人肯护的。' },
};
